using System.ComponentModel.DataAnnotations;
namespace RaceDay.Mvc.Models;
public record UserDto(int Id,string FullName,string Email,string Role,string? ProfileImageUrl=null);
public class EventDto { public int Id{get;set;} public string Name{get;set;}=""; public string Description{get;set;}=""; public DateTime EventDate{get;set;} public string Location{get;set;}=""; public double DistanceKm{get;set;} public string EventType{get;set;}="Run"; public int OrganiserId{get;set;} public string? BannerImageUrl{get;set;} public List<CategoryDto> Categories{get;set;}=[]; }
public class CategoryDto { public int Id{get;set;} public int EventId{get;set;} public string Name{get;set;}=""; public int? MinimumAge{get;set;} public int? MaximumAge{get;set;} public double? DistanceKm{get;set;} }
public class EnrollmentDto { public int Id{get;set;} public int EventId{get;set;} public int CategoryId{get;set;} public int ParticipantId{get;set;} public string? ParticipantName{get;set;} public string? Category{get;set;} public string Status{get;set;}="Confirmed"; public DateTime EnrolledAtUtc{get;set;} public EventDto? Event{get;set;} public CategoryDto? CategoryInfo{get;set;} }
public class ResultDto { public int Id{get;set;} public string? EventName{get;set;} public DateTime EventDate{get;set;} public string? Category{get;set;} public int TotalFinishers{get;set;} public string? Participant{get;set;} public TimeSpan FinishTime{get;set;} public int FinishingPosition{get;set;} }
public class RegisterVm { [Required] public string FullName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; [Required,MinLength(8)] public string Password{get;set;}=""; [Required] public string Role{get;set;}="Participant"; }
public class LoginVm { [Required,EmailAddress] public string Email{get;set;}=""; [Required] public string Password{get;set;}=""; }
public class EventVm { public int Id{get;set;} [Required,MaxLength(120)] public string Name{get;set;}=""; [Required,MaxLength(500)] public string Description{get;set;}=""; [Required] public DateTime EventDate{get;set;}=DateTime.Now.AddDays(30); [Required] public string Location{get;set;}=""; [Range(.1,1000)] public double DistanceKm{get;set;}=5; [Required] public string EventType{get;set;}="Run"; public IFormFile? Banner{get;set;} }
public class CategoryVm { public int EventId{get;set;} [Required] public string Name{get;set;}=""; public int? MinimumAge{get;set;} public int? MaximumAge{get;set;} public double? DistanceKm{get;set;} }
public class ResultVm { public int EnrollmentId{get;set;} public string FinishTime{get;set;}="00:30:00"; public int FinishingPosition{get;set;}=1; }
public class ProfileVm { public string? ProfileImageUrl{get;set;} [Required] public string FullName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; public IFormFile? Picture{get;set;} }
